namespace OpenTPW;

/// <summary>
/// Approximation register of guest arrivals (docs/GUESTS.md, "Arrivals"). Each entry is tagged
/// <c>[APPROX:ARRIVAL-NNN]</c> at its code site; the arrival rule itself is traced from the Mac binary.
/// </summary>
public static class ArrivalApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("ARRIVAL-001", "VEHICLE STOP: the arrival update drives the level's bus, seaplane or Ferry as tp.exe 0x4CF3E0 does (dispatch by group size 0x51A2F0, guests only at status 2, the vehicle's own script for the drive), but around the stop OpenTPW differs: a leaving guest waits at its lane's first cell and boards at status 4, one per stop cell and turn in update order, where the original's state 21 (0x500BD0) first walks it, at status 1 to 3, to the vehicle's two stop cells (the cell 0x4D8650 returns and its +x neighbour for the bus, the two cells two rows lower for the seaplane and Ferry, 0x51AAD0) with three world draws and state 20, and boards the head of its cell's thing list; the pick-up test 0x51A9D0 reads the head thing of those four cells for a guest in state 21, where OpenTPW asks for any guest in state 21; the arrival update runs before the guest updates of a turn, where the original runs it after the thing sweep (end of 0x516380); and an imported original save starts with no vehicle at work (its +0x1DA72A word is not decoded)"),
		("ARRIVAL-002", "ONLINE VISIT GROUP: the cut matches tp.exe 0x4CF5B0 (counted guests plus group at most 500 while the GameType word 0xFB3B7C is 1, else 1500): a visit of a published park sets GameType 1 (0x4C0830, the park-info dialog's completion), and the visited park runs the arrival step (main loop 0x54F760 -> 0x5166B0 -> 0x516380 -> 0x4CF3E0); the factor matches too (0.8 while the weather thing's +0x30 word, mCurrentDrops, is positive, 0x4CF60E; the drop ramp is AUDIO-025..027, 029, 030). What differs on a visit: OpenTPW reads the group's Arrival.* keys from Standard.sam where the original loads data\\levels\\online_Standard.sam and the level's online_Standard.sam for GameType 1 (0x51573C, 0x515755; Arrival.PointsPerVisitor 2 instead of 6), and a read-only visit has no economy, so its groups count 0 park points"),
		("ARRIVAL-003", "POINTS: the counts-test (tp.exe 0x4DD920) and the kind filter (Info.WhichUIType 0 or 2, 0x4C8240) are applied, the coaster test 0x441970 as CoasterRide.AcceptsGuests and the kart and water track word +0x2C as BumpController.IsTrackValid. Residuals: OpenTPW's coaster test also needs 3 track samples and has no not-the-coaster-being-edited term (0x790FEC, COAST-024), and a kart or water ride's track word is false before its first circuit walk where the original's constructor sets 1 (0x4DB0DF); a coaster imported from an original save has no controller (its track is not imported, SAVE-920 to SAVE-923), so it gives no points where the original counts it"),
		("ARRIVAL-005", "FIRST PURCHASE ON IMPORT: an object imported from an original save sets its type's first-purchase turn to the import turn while it is 0; the original restores every type's record (+0x1C first purchase, +0x18 copies) verbatim from the save's object-control block (the world loader 0x5179C0 reads it with 0x4D3AA0 at 0x5181E7: 150 records of 32 bytes, the count and the search key), adds zeroed records for types missing from it (0x4D3E00 after the load) and stamps a turn only into a record still at 0 (0x4DB690); OpenTPW keeps that block opaque. Fixed items of a new park agree: the park gates and traffic lights are built after the turn is set to 0 (0x515865)"),
		("ARRIVAL-006", "BOOTH WAIT: an expensive verdict holds the guest for 50 + R % 50 state-4 updates, one per executed park turn, and the verdict runs again on the turn after (tp.exe 0x4FF9D0), N + 1 turns in all; OpenTPW times those N + 1 turns as seconds of the frame clock (248 ms each) rather than counting park-turn boundaries, does not drop the turns the original's loop can drop (at most 3 per pass, 0x54F680), and draws from the guest stream rather than the world generator 0x516330 (DET-014); a closed park's state 3 (0x4FF966) first counts any remaining wait +0x200 down, one per guest update, before it sends the guest home, where OpenTPW sends it home at once (the wait is 0 on both of OpenTPW's paths into it: a guest arriving at the booth and one that has just paid after its wait ran out)"),
	};
}
